TYPE GateState :
(
    IDLE    := 0,
    OPENING := 1,
    CLOSING := 2,
    FAULT   := 3
);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    state        : GateState;
    openBtnPrev  : BOOL;
    closeBtnPrev : BOOL;
    openRising   : BOOL;
    closeRising  : BOOL;
END_VAR

openRising  := openBtn  AND NOT openBtnPrev;
closeRising := closeBtn AND NOT closeBtnPrev;
openBtnPrev  := openBtn;
closeBtnPrev := closeBtn;

CASE state OF
    IDLE:
        IF openRising AND NOT openLimit THEN
            state := OPENING;
        ELSIF closeRising AND NOT closeLimit THEN
            state := CLOSING;
        END_IF

    OPENING:
        IF obstacle THEN
            state     := FAULT;
            errorFlag := TRUE;
        ELSIF openLimit THEN
            state := IDLE;
        END_IF

    CLOSING:
        IF obstacle THEN
            state := OPENING;
        ELSIF closeLimit THEN
            state := IDLE;
        END_IF

    FAULT:
        IF openBtn AND closeBtn THEN
            state     := IDLE;
            errorFlag := FALSE;
        END_IF
END_CASE

IF state = OPENING THEN
    motorUp   := TRUE;
    motorDown := FALSE;
ELSIF state = CLOSING THEN
    motorUp   := FALSE;
    motorDown := TRUE;
ELSE
    motorUp   := FALSE;
    motorDown := FALSE;
END_IF
END_FUNCTION_BLOCK
